namespace smbios {

/// @brief Failure reasons of acquisition and parsing.
enum class Error : std::uint8_t {
  not_available,        ///< no SMBIOS on this system (or platform unsupported)
  permission_denied,    ///< caller lacks rights to read the table
  io_error,             ///< read failed for another reason
  invalid_entry_point,  ///< anchor wrong, entry point truncated or length byte invalid
  malformed_table,      ///< no structure readable, or table outside the dump
};

}  // namespace smbios

/// @brief Formats an Error as a short message; accepts the std::string_view format spec.
template <>
struct std::formatter<smbios::Error> : std::formatter<std::string_view> {
  /// @brief Writes the message for `e` to `ctx`.
  /// @param e error to format
  /// @param ctx format context
  /// @return iterator past the written text
  template <class FormatContext>
  auto format(smbios::Error e, FormatContext& ctx) const {
    std::string_view message = "unknown error";
    switch (e) {
      case smbios::Error::not_available:
        message = "SMBIOS not available";
        break;
      case smbios::Error::permission_denied:
        message = "permission denied";
        break;
      case smbios::Error::io_error:
        message = "I/O error";
        break;
      case smbios::Error::invalid_entry_point:
        message = "invalid entry point";
        break;
      case smbios::Error::malformed_table:
        message = "malformed table";
        break;
    }
    return std::formatter<std::string_view>::format(message, ctx);
  }
};

// include/smbios/bytes.hpp

namespace smbios {

/// @brief Unsigned integer types readable from SMBIOS data (excludes bool, which is unsigned_integral).
template <class T>
concept Unsigned = std::unsigned_integral<T> && !std::same_as<T, bool>;

/// @brief Reads a little-endian unsigned integer.
/// @param bytes data to read from
/// @param offset position of the first byte of the value
/// @return value, or nullopt if `[offset, offset + sizeof(T))` does not lie within `bytes`
template <Unsigned T>
[[nodiscard]] constexpr std::optional<T> read_le(std::span<const std::byte> bytes, std::size_t offset) noexcept {
  if (offset > bytes.size() || bytes.size() - offset < sizeof(T)) return std::nullopt;
  T value = 0;
  for (std::size_t i = 0; i < sizeof(T); ++i)
    value = static_cast<T>(value | (static_cast<T>(bytes[offset + i]) << (8 * i)));
  return value;
}

}  // namespace smbios

// include/smbios/version.hpp

namespace smbios {

/// @brief SMBIOS specification version of a table.
struct Version {
  std::uint8_t major{};   ///< major version
  std::uint8_t minor{};   ///< minor version
  std::uint8_t docrev{};  ///< 0 for 2.x entry points

  /// @brief Compares major, then minor, then docrev.
  /// @return ordering of the two versions
  friend constexpr auto operator<=>(const Version&, const Version&) = default;
};

}  // namespace smbios

/// @brief Formats a Version as `major.minor.docrev`; accepts the std::string_view format spec.
template <>
struct std::formatter<smbios::Version> : std::formatter<std::string_view> {
  /// @brief Writes `v` to `ctx`.
  /// @param v version to format
  /// @param ctx format context
  /// @return iterator past the written text
  template <class FormatContext>
  auto format(const smbios::Version& v, FormatContext& ctx) const {
    return std::formatter<std::string_view>::format(std::format("{}.{}.{}", v.major, v.minor, v.docrev), ctx);
  }
};

