namespace smbios {

/// @brief Non-owning view of one structure. Valid while the underlying bytes live.
class RawStructure {
 public:
  /// @return structure type (header offset 0x00)
  [[nodiscard]] std::uint8_t type() const noexcept;
  /// @return formatted area length, header included (header offset 0x01)
  [[nodiscard]] std::uint8_t length() const noexcept;
  /// @return structure handle (header offset 0x02)
  [[nodiscard]] std::uint16_t handle() const noexcept;
  /// @return SMBIOS version of the containing table
  [[nodiscard]] Version version() const noexcept;
  /// @return formatted area, header included; exactly length() bytes
  [[nodiscard]] std::span<const std::byte> formatted() const noexcept;

  /// @brief Looks up a string of the string set.
  /// @param index 1-based string number
  /// @return string as stored; nullopt for index 0 or an index beyond the string set
  [[nodiscard]] std::optional<std::string_view> string(std::uint8_t index) const noexcept;

  /// @brief Looks up the string referenced by the index byte at `offset`.
  /// @param offset offset of the index byte from the start of the structure
  /// @return string as stored; nullopt if offset >= length() or the index refers to no string
  [[nodiscard]] std::optional<std::string_view> string_at(std::size_t offset) const noexcept;

  /// @brief Reads a little-endian field of the formatted area.
  /// @param offset offset of the field from the start of the structure
  /// @return field value; nullopt if it does not lie completely within length()
  template <Unsigned T>
  [[nodiscard]] std::optional<T> field(std::size_t offset) const noexcept {
    return read_le<T>(formatted_, offset);
  }

 private:
  friend class StructureView;
  RawStructure(std::span<const std::byte> formatted, std::span<const std::byte> strings, Version version) noexcept;

  std::span<const std::byte> formatted_;  // invariant: size() >= 4
  std::span<const std::byte> strings_;    // NUL-separated, no trailing NUL; empty for `00 00`
  Version version_;
};

/// @brief Forward range over the structures of a table. Stops after type 127, at the end of the
///        bytes, or before the first malformed structure.
///
/// Malformed: fewer than 4 header bytes, length below 4, formatted area beyond the bytes, or no
/// double NUL terminating the string set.
class StructureView : public std::ranges::view_interface<StructureView> {
 public:
  /// @brief Forward iterator yielding RawStructure by value. A value-initialized iterator is the end.
  class iterator {
   public:
    using value_type = RawStructure;                     ///< element type
    using difference_type = std::ptrdiff_t;              ///< distance type
    using iterator_concept = std::forward_iterator_tag;  ///< models std::forward_iterator

    /// @brief Creates an end iterator.
    iterator() = default;

    /// @return current structure; the iterator must not be the end
    [[nodiscard]] RawStructure operator*() const noexcept;

    /// @brief Advances to the next structure, or to the end.
    /// @return `*this`
    iterator& operator++() noexcept;

    /// @brief Advances to the next structure, or to the end.
    /// @return iterator before advancing
    iterator operator++(int) noexcept {
      auto old = *this;
      ++*this;
      return old;
    }

    /// @brief Compares positions; iterators must belong to the same view.
    /// @return true if both refer to the same structure or both are the end
    friend bool operator==(const iterator& a, const iterator& b) noexcept { return a.rest_.data() == b.rest_.data(); }

   private:
    friend class StructureView;
    iterator(std::span<const std::byte> rest, Version version) noexcept;

    std::span<const std::byte> rest_;  // from current structure to end of table; empty means end
    std::size_t size_{};               // current structure including strings and double NUL
    Version version_;
  };

  /// @brief Creates an empty view.
  StructureView() = default;

  /// @brief Creates a view over table bytes.
  /// @param table structure table; must outlive the view and every RawStructure obtained from it
  /// @param version SMBIOS version passed on to each RawStructure
  StructureView(std::span<const std::byte> table, Version version) noexcept;

  /// @return iterator to the first structure, or end() if it is malformed or absent
  [[nodiscard]] iterator begin() const noexcept;
  /// @return end iterator (value-initialized)
  // NOLINTNEXTLINE(readability-convert-member-functions-to-static): range interface member
  [[nodiscard]] iterator end() const noexcept { return {}; }

 private:
  std::span<const std::byte> table_;
  Version version_;
};

/// @brief Range adaptor keeping structures of one type. The result is a std::views::filter view,
///        which is not const-iterable.
/// @param type structure type to keep
/// @return adaptor for use with `|`
inline auto of_type(std::uint8_t type) {
  return std::views::filter([type](const RawStructure& s) { return s.type() == type; });
}

}  // namespace smbios

// StructureView holds no data of its own; its iterators stay valid after it is destroyed.
/// @cond
template <>
inline constexpr bool std::ranges::enable_borrowed_range<smbios::StructureView> = true;
/// @endcond

