namespace smbios {

/// @brief Reasons a structure cannot be decoded into a typed record.
enum class DecodeError : std::uint8_t {
  too_short,   ///< length() below the type's minimum
  wrong_type,  ///< type() differs from type_id
};

/// @brief A typed record that can be decoded from a RawStructure.
///
/// `T::type_id` is the structure type; `T::decode` checks type() and the minimum length, then reads
/// the fields. User-defined records use the same interface as the built-in ones.
template <class T>
concept Decoder = requires(const RawStructure& r) {
  { T::type_id } -> std::convertible_to<std::uint8_t>;
  { T::decode(r) } -> std::same_as<std::expected<T, DecodeError>>;
};

}  // namespace smbios

