/// @brief Raw table bytes as acquired from the platform or a dump.
struct RawTable {
  std::vector<std::byte> bytes;           ///< structure table
  Version version;                        ///< SMBIOS version of the table
  std::optional<EntryPoint> entry_point;  ///< empty on Windows
};

/// @brief Owning, immutable SMBIOS table.
///
/// Every RawStructure, StructureView, decoded record, string_view and span obtained from a Table
/// points into its buffer and is valid while that Table lives. Bind the result of parse() or load_dump() to a
/// variable before iterating: `for (auto s : load_dump(p)->structures())` dangles.
class Table {
 public:
  /// @return view over all structures, up to and including type 127
  [[nodiscard]] StructureView structures() const noexcept;
  /// @return SMBIOS version of the table
  [[nodiscard]] Version version() const noexcept;
  /// @return entry point, if the source provided one
  [[nodiscard]] const std::optional<EntryPoint>& entry_point() const noexcept;

  /// @brief Decodes all structures of type D::type_id.
  /// @return records that decode successfully, in table order
  template <Decoder D>
  [[nodiscard]] std::vector<D> get() const;

  /// @brief Decodes the first structure of type D::type_id that decodes successfully.
  /// @return record, or nullopt if there is none
  template <Decoder D>
  [[nodiscard]] std::optional<D> get_one() const;

  /// @brief Decodes the structure a handle field refers to.
  /// @param handle handle as read from a record field
  /// @return record; nullopt for no handle, 0xFFFE/0xFFFF, unknown handle, type mismatch or decode failure
  template <Decoder D>
  [[nodiscard]] std::optional<D> resolve(std::optional<std::uint16_t> handle) const;

 private:
  friend std::expected<Table, Error> parse(RawTable raw);
  explicit Table(RawTable raw) noexcept;

  RawTable raw_;
};

template <Decoder D>
std::vector<D> Table::get() const {
  std::vector<D> out;
  for (const RawStructure s : structures() | of_type(D::type_id))
    if (auto record = D::decode(s)) out.push_back(*std::move(record));
  return out;
}

template <Decoder D>
std::optional<D> Table::get_one() const {
  for (const RawStructure s : structures() | of_type(D::type_id))
    if (auto record = D::decode(s)) return *std::move(record);
  return std::nullopt;
}

template <Decoder D>
std::optional<D> Table::resolve(std::optional<std::uint16_t> handle) const {
  if (!handle || *handle == 0xFFFE || *handle == 0xFFFF) return std::nullopt;
  const StructureView view = structures();
  const auto it = std::ranges::find(view, *handle, &RawStructure::handle);
  if (it == view.end() || (*it).type() != D::type_id) return std::nullopt;
  auto record = D::decode(*it);
  if (!record) return std::nullopt;
  return *std::move(record);
}

/// @brief Creates a Table from acquired bytes.
/// @param raw table bytes, version and optional entry point; ownership is taken
/// @return Table, or Error::malformed_table if the first structure is unreadable
[[nodiscard]] std::expected<Table, Error> parse(RawTable raw);

/// @brief Creates a Table from a copy of `table`; entry_point() is empty.
/// @param table structure table bytes
/// @param version SMBIOS version of the table
/// @return Table, or Error::malformed_table if the first structure is unreadable
[[nodiscard]] std::expected<Table, Error> parse(std::span<const std::byte> table, Version version);

/// @brief Parses a `dmidecode --dump-bin` image: entry point at offset 0, table at `table_address`.
