namespace smbios {

/// @brief A spec enumeration: scoped enum with an ADL-visible `name(E)` returning its spec name.
///
/// `name` returns nullopt for values without a name; the enum keeps such values unchanged.
template <class E>
concept SpecEnum = std::is_scoped_enum_v<E> && requires(E e) {
  { name(e) } -> std::same_as<std::optional<std::string_view>>;
};

}  // namespace smbios

/// @brief Formats a SpecEnum as its name, or `Unknown (0xNN)` with 2 * sizeof(E) upper-case hex digits;
///        accepts the std::string_view format spec.
template <smbios::SpecEnum E>
// NOLINTNEXTLINE(bugprone-std-namespace-modification): SpecEnum admits only program-defined enums
struct std::formatter<E, char> : std::formatter<std::string_view, char> {
  /// @brief Writes the name of `e` to `ctx`.
  /// @param e value to format
  /// @param ctx format context
  /// @return iterator past the written text
  template <class FormatContext>
  auto format(E e, FormatContext& ctx) const {
    if (const auto text = name(e)) return std::formatter<std::string_view, char>::format(*text, ctx);
    return std::formatter<std::string_view, char>::format(
        std::format("Unknown (0x{:0{}X})", std::to_underlying(e), 2 * sizeof(E)), ctx);
  }
};

