// src/types/chassis.cpp

namespace smbios {
namespace detail {

inline constexpr std::size_t kElementsOffset = 0x15;

inline std::optional<std::uint8_t> unless_zero(const RawStructure& s, std::size_t offset) {
  const auto value = s.field<std::uint8_t>(offset);
  if (value == 0) return std::nullopt;
  return value;
}

}  // namespace detail
using namespace detail;

inline std::expected<ChassisInfo, DecodeError> ChassisInfo::decode(const RawStructure& s) {
  if (s.type() != type_id) return std::unexpected(DecodeError::wrong_type);
  if (s.length() < 0x09) return std::unexpected(DecodeError::too_short);
  const std::uint8_t type = s.field<std::uint8_t>(0x05).value_or(0);
  const auto count = s.field<std::uint8_t>(0x13);
  const auto element_length = s.field<std::uint8_t>(0x14);
  const std::size_t sku_offset = kElementsOffset + (std::size_t{count.value_or(0)} * element_length.value_or(0));
  const bool elements_inside = sku_offset <= s.length();
  return ChassisInfo{
      .manufacturer = s.string_at(0x04),
      .type = ChassisType{static_cast<std::uint8_t>(type & 0x7FU)},
      .lock_present = (type & 0x80U) != 0,
      .version = s.string_at(0x06),
      .serial_number = s.string_at(0x07),
      .asset_tag = s.string_at(0x08),
      .boot_up_state = s.field<std::uint8_t>(0x09),
      .power_supply_state = s.field<std::uint8_t>(0x0A),
      .thermal_state = s.field<std::uint8_t>(0x0B),
      .security_status = s.field<std::uint8_t>(0x0C),
      .oem_defined = s.field<std::uint32_t>(0x0D),
      .height_u = unless_zero(s, 0x11),
      .power_cord_count = unless_zero(s, 0x12),
      .contained_element_count = count,
      .contained_element_length = element_length,
      .contained_elements = elements_inside ? s.formatted().subspan(kElementsOffset, sku_offset - kElementsOffset)
                                            : std::span<const std::byte>{},
      .sku_number = elements_inside ? s.string_at(sku_offset) : std::nullopt,
  };
}

}  // namespace smbios

