// src/types/memory_device.cpp

namespace smbios {
namespace detail {

inline std::optional<std::uint16_t> read_width(const RawStructure& s, std::size_t offset) {
  const std::uint16_t width = s.field<std::uint16_t>(offset).value_or(0);
  if (width == 0xFFFF) return std::nullopt;
  return width;
}

// WORD 0x0C: 0 empty slot, 0xFFFF unknown, 0x7FFF defers to the extended DWORD in MiB (2.7),
// bit 15 selects KiB instead of MiB.
inline std::optional<std::uint64_t> read_size_bytes(const RawStructure& s) {
  const std::uint16_t size = s.field<std::uint16_t>(0x0C).value_or(0);
  if (size == 0xFFFF) return std::nullopt;
  if (size == 0x7FFF) {
    return s.field<std::uint32_t>(0x1C).transform(
        [](std::uint32_t extended) { return (extended & 0x7FFF'FFFFU) * kMiB; });
  }
  if ((size & 0x8000U) != 0) return (size & 0x7FFFU) * kKiB;
  return size * kMiB;
}

// Speed WORD at `offset`: 0 unknown, 0xFFFF defers to the DWORD at `extended_offset` (3.3, bits 30:0, 0 unknown).
inline std::optional<std::uint32_t> read_speed(const RawStructure& s, std::size_t offset, std::size_t extended_offset) {
  const auto speed = s.field<std::uint16_t>(offset);
  if (speed == 0) return std::nullopt;
  if (speed != 0xFFFF) return speed;
  const auto extended =
      s.field<std::uint32_t>(extended_offset).transform([](std::uint32_t value) { return value & 0x7FFF'FFFFU; });
  if (extended == 0U) return std::nullopt;
  return extended;
}

inline std::optional<std::uint8_t> read_rank(const RawStructure& s) {
  const auto rank = s.field<std::uint8_t>(0x1B).transform(
      [](std::uint8_t attributes) { return static_cast<std::uint8_t>(attributes & 0x0FU); });
  if (rank == 0) return std::nullopt;
  return rank;
}

inline std::optional<std::uint16_t> read_voltage_mv(const RawStructure& s, std::size_t offset) {
  const auto voltage = s.field<std::uint16_t>(offset);
  if (voltage == 0) return std::nullopt;
  return voltage;
}

}  // namespace detail
using namespace detail;

inline std::expected<MemoryDevice, DecodeError> MemoryDevice::decode(const RawStructure& s) {
  if (s.type() != type_id) return std::unexpected(DecodeError::wrong_type);
  if (s.length() < 0x15) return std::unexpected(DecodeError::too_short);
  return MemoryDevice{
      .array_handle = s.field<std::uint16_t>(0x04).value_or(0),
      .error_info_handle = s.field<std::uint16_t>(0x06).value_or(0),
      .total_width_bits = read_width(s, 0x08),
      .data_width_bits = read_width(s, 0x0A),
      .size_bytes = read_size_bytes(s),
      .form_factor = MemoryFormFactor{s.field<std::uint8_t>(0x0E).value_or(0)},
      .device_set = s.field<std::uint8_t>(0x0F).value_or(0),
      .device_locator = s.string_at(0x10),
      .bank_locator = s.string_at(0x11),
      .memory_type = MemoryType{s.field<std::uint8_t>(0x12).value_or(0)},
      .type_detail = s.field<std::uint16_t>(0x13).value_or(0),
      .speed_mts = read_speed(s, 0x15, 0x54),
      .manufacturer = s.string_at(0x17),
      .serial_number = s.string_at(0x18),
      .asset_tag = s.string_at(0x19),
      .part_number = s.string_at(0x1A),
      .rank = read_rank(s),
      .configured_speed_mts = read_speed(s, 0x20, 0x58),
      .min_voltage_mv = read_voltage_mv(s, 0x22),
      .max_voltage_mv = read_voltage_mv(s, 0x24),
      .configured_voltage_mv = read_voltage_mv(s, 0x26),
  };
}

}  // namespace smbios

// src/types/memory_mapped_address.cpp

namespace smbios {

inline std::expected<MemoryArrayMappedAddress, DecodeError> MemoryArrayMappedAddress::decode(const RawStructure& s) {
  if (s.type() != type_id) return std::unexpected(DecodeError::wrong_type);
  if (s.length() < 0x0F) return std::unexpected(DecodeError::too_short);
  const std::uint32_t start_kib = s.field<std::uint32_t>(0x04).value_or(0);
  const std::uint32_t end_kib = s.field<std::uint32_t>(0x08).value_or(0);
  // 0xFFFFFFFF defers to the QWORDs in bytes (2.7); the DWORDs name the first and the last KiB.
  const bool extended = start_kib == 0xFFFF'FFFFU && s.length() >= 0x1F;
  return MemoryArrayMappedAddress{
      .start_address = extended ? s.field<std::uint64_t>(0x0F).value_or(0) : start_kib * kKiB,
      .end_address = extended ? s.field<std::uint64_t>(0x17).value_or(0) : (end_kib * kKiB) + (kKiB - 1),
      .array_handle = s.field<std::uint16_t>(0x0C).value_or(0),
      .partition_width = s.field<std::uint8_t>(0x0E).value_or(0),
  };
}

}  // namespace smbios

// src/types/processor.cpp

namespace smbios {
namespace detail {

inline std::uint16_t read_family(const RawStructure& s) {
  const std::uint8_t family = s.field<std::uint8_t>(0x06).value_or(0);
  if (family != 0xFE) return family;
  return s.field<std::uint16_t>(0x28).value_or(family);
}

inline std::optional<std::uint16_t> read_current_voltage_mv(std::uint8_t voltage) {
  if ((voltage & 0x80U) == 0) return std::nullopt;
  return static_cast<std::uint16_t>((voltage & 0x7FU) * 100U);
}

inline std::optional<std::uint8_t> read_legacy_voltages(std::uint8_t voltage) {
  if ((voltage & 0x80U) != 0) return std::nullopt;
  return static_cast<std::uint8_t>(voltage & 0x07U);
}

inline std::optional<std::uint16_t> nonzero_word(const RawStructure& s, std::size_t offset) {
  const auto value = s.field<std::uint16_t>(offset);
  if (value == 0) return std::nullopt;
  return value;
}

inline std::optional<std::uint16_t> cache_handle(const RawStructure& s, std::size_t offset) {
  const auto handle = s.field<std::uint16_t>(offset);
  if (handle == 0xFFFF) return std::nullopt;
  return handle;
}

// WORD where 0 means unknown and 0xFFFF is reserved.
inline std::optional<std::uint16_t> known_word(const RawStructure& s, std::size_t offset) {
  const auto value = s.field<std::uint16_t>(offset);
  if (value == 0 || value == 0xFFFF) return std::nullopt;
  return value;
}

// 2.5 count byte; 0xFF defers to the 3.0 WORD at `extended_offset`.
inline std::optional<std::uint16_t> count(const RawStructure& s, std::size_t offset, std::size_t extended_offset) {
  const auto value = s.field<std::uint8_t>(offset);
  if (value == 0) return std::nullopt;
  if (value != 0xFF) return value;
  return known_word(s, extended_offset);
}

}  // namespace detail
using namespace detail;

inline std::expected<Processor, DecodeError> Processor::decode(const RawStructure& s) {
  if (s.type() != type_id) return std::unexpected(DecodeError::wrong_type);
  if (s.length() < 0x1A) return std::unexpected(DecodeError::too_short);
  const std::uint8_t voltage = s.field<std::uint8_t>(0x11).value_or(0);
  return Processor{
      .socket_designation = s.string_at(0x04),
      .type = ProcessorType{s.field<std::uint8_t>(0x05).value_or(0)},
      .family = read_family(s),
      .manufacturer = s.string_at(0x07),
      .id = s.field<std::uint64_t>(0x08).value_or(0),
      .version = s.string_at(0x10),
      .voltage_mv = read_current_voltage_mv(voltage),
      .legacy_voltages = read_legacy_voltages(voltage),
      .external_clock_mhz = nonzero_word(s, 0x12),
      .max_speed_mhz = nonzero_word(s, 0x14),
      .current_speed_mhz = nonzero_word(s, 0x16),
      .status = s.field<std::uint8_t>(0x18).value_or(0),
      .upgrade = s.field<std::uint8_t>(0x19).value_or(0),
      .l1_cache_handle = cache_handle(s, 0x1A),
      .l2_cache_handle = cache_handle(s, 0x1C),
      .l3_cache_handle = cache_handle(s, 0x1E),
      .serial_number = s.string_at(0x20),
      .asset_tag = s.string_at(0x21),
      .part_number = s.string_at(0x22),
      .core_count = count(s, 0x23, 0x2A),
      .core_enabled = count(s, 0x24, 0x2C),
      .thread_count = count(s, 0x25, 0x2E),
      .characteristics = s.field<std::uint16_t>(0x26),
      .thread_enabled = known_word(s, 0x30),
  };
}

}  // namespace smbios

// src/types/system.cpp

namespace smbios {
namespace detail {

inline constexpr std::size_t kUuidOffset = 0x08;
inline constexpr std::size_t kUuidSize = 16;
inline constexpr Version kLittleEndianUuid{.major = 2, .minor = 6, .docrev = 0};

inline std::optional<Uuid> read_uuid(const RawStructure& s) {
  if (s.length() < kUuidOffset + kUuidSize) return std::nullopt;
  Uuid out;
  std::ranges::transform(s.formatted().subspan(kUuidOffset, kUuidSize), out.bytes.begin(),
                         [](std::byte b) { return std::to_integer<std::uint8_t>(b); });
  if (s.version() >= kLittleEndianUuid) {
    const std::span bytes{out.bytes};
    std::ranges::reverse(bytes.subspan(0, 4));
    std::ranges::reverse(bytes.subspan(4, 2));
    std::ranges::reverse(bytes.subspan(6, 2));
  }
  return out;
}

}  // namespace detail
using namespace detail;

inline std::expected<SystemInfo, DecodeError> SystemInfo::decode(const RawStructure& s) {
  if (s.type() != type_id) return std::unexpected(DecodeError::wrong_type);
  if (s.length() < 0x08) return std::unexpected(DecodeError::too_short);
  return SystemInfo{
      .manufacturer = s.string_at(0x04),
      .product_name = s.string_at(0x05),
      .version = s.string_at(0x06),
      .serial_number = s.string_at(0x07),
      .uuid = read_uuid(s),
      .wake_up_type = s.field<std::uint8_t>(0x18),
      .sku_number = s.string_at(0x19),
      .family = s.string_at(0x1A),
  };
}

}  // namespace smbios

